const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'y1 = sin θ（振幅 1）' },
      { kind: 'text', payload: 'y2 = 0.5 sin θ（振幅 0.5）' },
      { kind: 'text', payload: 'y = y1 + y2（振幅 1.5）' },
      { kind: 'text', payload: 'θ' },
      { kind: 'text', payload: 'y' },
      { kind: 'text', payload: '1.5' },
      { kind: 'text', payload: '−1.5' },
      { kind: 'text', payload: 'O' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var leftX = 78;
    var rightX = Math.max(leftX + 200, W - 54);
    var plotTop = 98;
    var plotBottom = Math.max(plotTop + 130, H - 56);
    var plotH = plotBottom - plotTop;
    var plotW = rightX - leftX;
    var centerY = plotTop + plotH / 2;
    var ampScale = (plotH / 2 - 14) / 1.6;
    if (ampScale < 6) { ampScale = 6; }

    var c1 = '#1f6fb2';
    var c2 = '#d9822b';
    var c3 = '#b03a2e';
    var cAxis = '#33414f';
    var cGuide = '#b03a2eaa';

    var paths = [];
    var nodes = [];

    function pathNode(id, cmds, fill, sw) {
      paths.push({ id: id, commands: cmds });
      var n = { type: 'path', pathId: id, fill: fill };
      if (sw) { n.stroke = { width: sw }; }
      nodes.push(n);
    }

    function lineNode(id, x1, y1, x2, y2, color, sw) {
      pathNode(id, [['M', x1, y1], ['L', x2, y2]], color, sw);
    }

    function label(i, x, y, h, v, color) {
      nodes.push({
        type: 'label',
        contentId: metrics[i].contentId,
        anchor: { x: x, y: y },
        hAlign: h,
        vAlign: v,
        color: color
      });
    }

    pathNode('h-axis', visualSdk.axis({ x0: leftX, y0: centerY, x1: rightX, y1: centerY, ticks: 8, tickLength: 6 }), cAxis, 1.6);
    pathNode('h-arrow', visualSdk.arrow(leftX, centerY, rightX, centerY), cAxis);
    pathNode('v-axis', visualSdk.axis({ x0: leftX, y0: centerY + 1.6 * ampScale, x1: leftX, y1: centerY - 1.6 * ampScale, ticks: 0, tickLength: 6 }), cAxis, 1.6);
    pathNode('v-arrow', visualSdk.arrow(leftX, centerY + 1.6 * ampScale, leftX, centerY - 1.6 * ampScale), cAxis);

    var marks = [-1.5, -1, -0.5, 0.5, 1, 1.5];
    for (var m = 0; m < marks.length; m++) {
      var my = centerY - marks[m] * ampScale;
      lineNode('v-tick-' + m, leftX - 5, my, leftX + 5, my, cAxis, 1.4);
    }

    function waveCmds(amp) {
      var pts = [];
      for (var i = 0; i <= 160; i++) {
        var s = i / 160;
        pts.push([leftX + s * plotW, centerY - amp * ampScale * Math.sin(2 * Math.PI * 2 * s)]);
      }
      return visualSdk.polyline(pts);
    }

    pathNode('wave-1', waveCmds(1), c1, 2.4);
    pathNode('wave-2', waveCmds(0.5), c2, 2.4);
    pathNode('wave-sum', waveCmds(1.5), c3, 3);

    var yPeak = centerY - 1.5 * ampScale;
    var px = leftX + plotW / 8;
    lineNode('guide-peak', px, yPeak, rightX, yPeak, cGuide, 1.2);
    lineNode('guide-amp', px, centerY, px, yPeak, cGuide, 1.2);
    pathNode('peak-dot', visualSdk.circle(px, yPeak, 4), c3);

    lineNode('lg-1', leftX, 28, leftX + 28, 28, c1, 3);
    lineNode('lg-2', leftX, 50, leftX + 28, 50, c2, 3);
    lineNode('lg-3', leftX, 72, leftX + 28, 72, c3, 3);

    label(0, leftX + 36, 28, 'left', 'middle', c1);
    label(1, leftX + 36, 50, 'left', 'middle', c2);
    label(2, leftX + 36, 72, 'left', 'middle', c3);
    label(5, leftX - 10, yPeak, 'right', 'middle', c3);
    label(6, leftX - 10, centerY + 1.5 * ampScale, 'right', 'middle', cAxis);
    label(7, leftX - 10, centerY + 6, 'right', 'top', cAxis);
    label(3, rightX + 6, centerY + 8, 'left', 'top', cAxis);
    label(4, leftX + 10, centerY - 1.6 * ampScale - 6, 'left', 'bottom', cAxis);

    return {
      schemaVersion: 1,
      sceneId: 'superposition-waves',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: nodes }
    };
  }
};
